source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    row_seps = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]

    def blocks(separators, size):
        result = []
        start = 0
        for sep in separators + [size]:
            if sep > start:
                result.append((start, sep))
            start = sep + 1
        return result

    row_blocks = blocks(row_seps, h)
    col_blocks = blocks(col_seps, w)
    cells = {}
    for i, (r0, r1) in enumerate(row_blocks):
        for j, (c0, c1) in enumerate(col_blocks):
            pixels = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0]
            if pixels:
                color = max(set(pixels), key=pixels.count)
                bitmap = [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
                cells[i, j] = (color, bitmap)

    output = [row[:] for row in grid]
    by_color = {}
    for position, (color, _) in cells.items():
        by_color.setdefault(color, []).append(position)

    for color, positions in by_color.items():
        if len(positions) != 3:
            continue
        rmin, rmax = min(r for r, _ in positions), max(r for r, _ in positions)
        cmin, cmax = min(c for _, c in positions), max(c for _, c in positions)
        if rmax - rmin != 1 or cmax - cmin != 1:
            continue
        missing = {(r, c) for r in range(rmin, rmax + 1) for c in range(cmin, cmax + 1)} - set(positions)
        if len(missing) != 1:
            continue
        mr, mc = next(iter(missing))
        source_r, source_c = rmin + rmax - mr, cmin + cmax - mc
        bitmap = cells[source_r, source_c][1]
        r0, r1 = row_blocks[mr]
        c0, c1 = col_blocks[mc]
        for dr in range(min(r1 - r0, len(bitmap))):
            for dc in range(min(c1 - c0, len(bitmap[dr]))):
                if bitmap[len(bitmap) - 1 - dr][len(bitmap[dr]) - 1 - dc] != 0:
                    output[r0 + dr][c0 + dc] = color
    return output
'''
